insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9d786cb9-4aa8-4740-8899-4c54e299ef8f', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Para explicar la replicación del ADN, inicialmente se propuso la teoría conservativa, según la cual se producen dos dobles hélices: una tiene las dos hebras molde y la otra las dos hebras nuevas (Imagen 1).</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b5-q97.webp" style="min-width:430px" loading="lazy" alt="Comparación de la replicación conservativa y semiconservativa del ADN."><figcaption>Comparación de la replicación conservativa y semiconservativa del ADN. Desliza para ver la figura completa.</figcaption></figure><p>Posteriormente, se realizaron experimentos encontrando que, de las dos hélices producidas, una tiene una hebra de la cadena original y otra hebra nueva (Imagen 2). Finalmente esta fue aceptada como la teoría correcta y es reconocida como la teoría semiconservativa:</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('dfc23c12-e7fe-4d13-a221-98ccb72dc087', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un grupo de estudiantes quiere saber por qué cuando llueve en la mañana se deteriora el estado de las plantas de su colegio y plantea como hipótesis que esto se debe a que únicamente entre las 8:00 a. m. y las 9:00 a. m. el agua de la lluvia tiene un pH menor que 6,0.</p><p>Los estudiantes deciden medir el pH del agua de lluvia durante un mismo día a distintas horas y obtienen los resultados que se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Hora</th><th scope="col">pH del agua de lluvia</th></tr></thead><tbody><tr><th scope="row">7:00 a. m.</th><td>6,4</td></tr><tr><th scope="row">8:00 a. m.</th><td>6,5</td></tr><tr><th scope="row">9:00 a. m.</th><td>6,4</td></tr><tr><th scope="row">10:00 a. m.</th><td>6,5</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ff735836-3e56-4666-8d3b-dac946f25252', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El ciclo del fósforo es un ciclo biogeoquímico que describe el movimiento de este elemento químico en un ecosistema.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b5-q99.webp" style="min-width:720px" loading="lazy" alt="Ciclo del fósforo: rocas, meteorización, fosfatos del suelo, plantas, animales y descomposición."><figcaption>Ciclo del fósforo: rocas, meteorización, fosfatos del suelo, plantas, animales y descomposición. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('0f66ec04-de04-43aa-a8f4-d71b0244871e', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La leishmaniasis es una enfermedad que se transmite por la picadura de mosquitos. En los primates, como los humanos y los monos, la enfermedad puede causar la muerte. Sin embargo, en otros mamíferos como cerdos salvajes o zarigüeyas no se desarrolla esta enfermedad. Existen controladores naturales de los mosquitos, como las lagartijas nocturnas.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b5-q100.webp" style="min-width:470px" loading="lazy" alt="Relación entre primates, cerdos, insectos transmisores y lagartijas depredadoras."><figcaption>Relación entre primates, cerdos, insectos transmisores y lagartijas depredadoras. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6d141a00-1c22-4d25-9062-c4c7b67de735', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La gráfica muestra el número de individuos de focas en la Antártida, cada 30 años desde 1860 hasta 2010.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b5-q101.webp" style="min-width:580px" loading="lazy" alt="Número de focas en la Antártida entre 1860 y 2010."><figcaption>Número de focas en la Antártida entre 1860 y 2010. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b0a14436-ed19-40fd-bae4-3dbdafcbb01d', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En una región vivía una especie de serpiente. En 1940, se introdujo otra especie de serpiente que se alimentaba de los mismos recursos que la serpiente nativa. Un grupo de científicos registró el número de individuos de cada población de serpientes cada diez años hasta que el año 1990. Los resultados se muestran en la gráfica.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b5-q103.webp" style="min-width:760px" loading="lazy" alt="Evolución del número de serpientes nativas e introducidas entre 1940 y 1990."><figcaption>Evolución del número de serpientes nativas e introducidas entre 1940 y 1990. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('cb3f1bc5-dd13-4020-8f05-aa10817ab03d', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La glándula tiroides se encarga, entre otras funciones, de la producción de las hormonas tiroideas T₃ y T₄. Ambas hormonas se componen de yodo, que debe obtenerse de la dieta para su utilización. La actividad de la tiroides se controla por la glándula pituitaria, la cual, cuando detecta un descenso en la concentración de las hormonas T₃ y T₄, estimula la actividad de la tiroides para aumentar su producción. La deficiencia de yodo en la dieta puede alterar al organismo.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('0739c9bb-5811-459f-b08a-152471346d59', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En el laboratorio se encuentran tres tipos de células pertenecientes a organismos pluricelulares. Al analizarlas con el microscopio, se registran los siguientes hallazgos.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Características</th><th scope="col">Célula X</th><th scope="col">Célula Y</th><th scope="col">Célula Z</th></tr></thead><tbody><tr><th scope="row">Número de cromosomas</th><td>40</td><td>20</td><td>36</td></tr><tr><th scope="row">Pared celular</th><td>Ausente</td><td>Ausente</td><td>Presente</td></tr><tr><th scope="row">Clorofila</th><td>Ausente</td><td>Ausente</td><td>Presente</td></tr><tr><th scope="row">Tipo de célula según la cantidad de cromosomas</th><td>Diploide</td><td>Haploide</td><td>Diploide</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4bcf4c63-9360-40d6-a2ec-efe101314457', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En el páncreas se produce una hormona llamada insulina, la cual permite el ingreso de los azúcares (glucosa) desde el torrente sanguíneo hacia las células. Esta hormona se produce a partir de un gen INS, el cual codifica una proteína llamada proinsulina, que posteriormente se modifica y genera insulina. En la figura se observa este proceso.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b5-q111.webp" style="min-width:260px" loading="lazy" alt="Gen INS, proinsulina y procesamiento para obtener insulina."><figcaption>Gen INS, proinsulina y procesamiento para obtener insulina. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4bca31c6-41fa-4888-a38c-cb4f5d6e89c5', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Los desiertos son ecosistemas extremos que presentan características climáticas limitantes para la vida, como poca disponibilidad de agua, altas temperaturas y radiación solar, y fuertes vientos. A pesar de estas condiciones, miles de personas y organismos viven en estos ecosistemas. A continuación, se muestran las fuentes de energía que utilizan los humanos en este hábitat.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Características de las fuentes de energía</th><th scope="col">Eólica</th><th scope="col">Paneles solares</th><th scope="col">Biocombustibles</th></tr></thead><tbody><tr><th scope="row">Gasto de agua</th><td>Baja</td><td>Baja</td><td>Alta</td></tr><tr><th scope="row">Necesidad de exposición solar</th><td>Nula</td><td>Alta</td><td>Media</td></tr><tr><th scope="row">Necesidad de alta velocidad de viento</th><td>Alta</td><td>Nula</td><td>Nula</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('812ff4a6-e012-4cde-af76-b961df124354', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En una población de gallina el tamaño del huevo y la resistencia de la cáscara están determinados por los siguientes genes.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Gen</th><th scope="col">Características</th></tr></thead><tbody><tr><th scope="row">G</th><td>Huevos grandes</td></tr><tr><th scope="row">g</th><td>Huevos pequeños</td></tr><tr><th scope="row">R</th><td>Cáscara resistente</td></tr><tr><th scope="row">r</th><td>Cáscara frágil</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('59c7e6b4-27d4-4047-becc-805980d13f86', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En una región del país se detectó un tipo de enfermedad genética que tiene un patrón de herencia ligada al sexo. El gen defectuoso se localiza solamente en el cromosoma X. Para padecer la enfermedad se requiere que, en el caso de los hombres, el cromosoma X porte el gen y en las mujeres que los dos cromosomas tengan el gen defectuoso. Un genetista está estudiando una familia que tiene cuatro hijos. Dos mujeres y dos hombres. Sus dos hijas son portadoras, pero no padecen de la enfermedad, y los hijos son sanos.</p>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '702fb08d-fc83-4ac6-88d1-7a30c6d9b310', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '9d786cb9-4aa8-4740-8899-4c54e299ef8f', 'Genética y herencia',
  '¿Por qué ocurrió el cambio en la explicación de este fenómeno?',
  array['Porque los investigadores cambiaron las preguntas iniciales, ya que querían saber sobre otros aspectos de la herencia.', 'Porque era necesario proponer una nueva hipótesis que explicara mejor la replicación de ADN que la teoría conservativa.', 'Porque los resultados del experimento permitieron comprobar la teoría semiconservativa en la replicación del ADN.', 'Porque la metodología que se utilizaba para explicar la replicación de ADN por la teoría conservativa se volvió obsoleta.'],
  'La evidencia experimental permite revisar los modelos científicos.', 'publicada', 'modelo', 'ae4b6f48be2a8c378866915e278714b4', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('702fb08d-fc83-4ac6-88d1-7a30c6d9b310', 2, 'Los resultados experimentales respaldaron una hebra original y una nueva en cada molécula hija, por lo que se sustituyó el modelo conservativo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '20d2f878-37a1-41ab-9316-16ae5813476c', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'dfc23c12-e7fe-4d13-a221-98ccb72dc087', 'Ecosistemas y ciclos',
  'De acuerdo con sus resultados, ellos notan que su hipótesis es incorrecta. Según su pregunta inicial, ¿qué pueden concluir los estudiantes?',
  array['El deterioro observado en las plantas durante la mañana se debe al cambio de temperatura en la región.', 'El pH del agua de la lluvia provoca el deterioro del suelo solo durante ciertas horas de la mañana.', 'El deterioro observado en las plantas durante la mañana se debe a la presencia de una plaga de insectos.', 'El pH del agua de la lluvia no provoca el deterioro de las plantas observado a ciertas horas de la mañana.'],
  'Distingue rechazar la hipótesis estudiada de demostrar una causa alternativa.', 'publicada', 'modelo', '679390307ba8fbe6deb44307d30346eb', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('20d2f878-37a1-41ab-9316-16ae5813476c', 3, 'Los valores medidos no respaldan un descenso del pH por debajo de 6,0 en el intervalo señalado. La opción compatible con el ejercicio rechaza esa explicación; los datos de un solo día no demuestran que el pH jamás pueda afectar a las plantas ni identifican otra causa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '17331a10-84f3-49aa-bc38-29fab07056d6', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'ff735836-3e56-4666-8d3b-dac946f25252', 'Ecosistemas y ciclos',
  'Según la figura, ¿de dónde provienen los fosfatos incorporados al suelo?',
  array['De varios procesos de lixiviación, precipitación y sedimentación en acuíferos.', 'De los fosfatos en solución presentes en los acuíferos cercanos al suelo.', 'De la meteorización de las rocas fosfatadas al entrar en contacto con el agua lluvia.', 'De los excrementos de los animales que son la fuente principal de fósforo para el suelo.'],
  'Sigue la flecha que conecta las rocas con los fosfatos del suelo.', 'publicada', 'modelo', '1195e62aabacb44c68e1f0e4b00e807b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('17331a10-84f3-49aa-bc38-29fab07056d6', 2, 'El esquema muestra que la meteorización libera fosfatos de las rocas hacia el suelo. La descomposición también recicla fósforo, pero la figura no establece que los excrementos sean la fuente principal.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1e96083a-502f-4dac-9166-b0899133f3bd', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '0f66ec04-de04-43aa-a8f4-d71b0244871e', 'Ecosistemas y ciclos',
  'Si ocurriera un cambio drástico en la temperatura, y este provocara la extinción de la población de lagartijas presentes en el ecosistema, las poblaciones de primates disminuirían y las de cerdos salvajes permanecerían estables. ¿Por qué ocurriría esto?',
  array['Porque los cerdos poseen una dieta muy diversa, por lo cual no se afectarían si los mosquitos desaparecieran.', 'Porque la dieta principal de los monos son las lagartijas, y ocasionaría una hambruna en las poblaciones de primates.', 'Porque la disminución de los depredadores de mosquitos causaría el aumento de primates infectados con la enfermedad.', 'Porque la disminución de los mosquitos evitaría que las poblaciones de cerdos se infecten y desarrollen la enfermedad.'],
  'Relaciona la pérdida de controladores naturales con la abundancia del vector.', 'publicada', 'modelo', '35c150719f578f9c384dbace9280ce82', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1e96083a-502f-4dac-9166-b0899133f3bd', 2, 'Según el modelo del ejercicio, menos depredadores permiten aumentar los insectos transmisores y las infecciones en primates. No se plantea que los primates se alimenten de lagartijas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'af44beb1-3a05-43f9-850c-2a8938a494a7', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '6d141a00-1c22-4d25-9062-c4c7b67de735', 'Ecosistemas y ciclos',
  'Con base en la información anterior, ¿cuál de las siguientes interpretaciones es válida?',
  array['El número de focas en 1950 era el mismo que en 1980.', 'El número de focas ha aumentado desde el año 1860.', 'El número de focas disminuyó en el año 1950.', 'El número de focas en 1860 era el mismo que en el año 1920.'],
  'Compara las alturas de las barras en orden temporal.', 'publicada', 'modelo', 'a8ccd6ef2a31b5aab9a610659b986087', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('af44beb1-3a05-43f9-850c-2a8938a494a7', 1, 'Las barras muestran un aumento de 7 a 20.000 individuos entre los extremos de la serie. Ninguna pareja citada en las otras opciones tiene valores iguales ni se muestra una disminución. El escaneo rotula 1960 donde el texto sugiere intervalos de 30 años; esa errata no altera la tendencia.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a1b09923-82b3-4244-a31c-87b0b50db12a', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'b0a14436-ed19-40fd-bae4-3dbdafcbb01d', 'Ecosistemas y ciclos',
  'Si las condiciones se mantienen, ¿qué predicción podría hacerse para cada población de serpientes?',
  array['El número de serpientes de la especie nativa disminuirá y el número de serpientes de la especie introducida aumentará.', 'El número de serpientes de la especie nativa aumentará y el número de serpientes de la especie introducida disminuirá.', 'El número de serpientes de las especies nativa e introducida disminuirá.', 'El número de serpientes de las especies nativa e introducida aumentará.'],
  'Lee primero la leyenda para no intercambiar las especies.', 'publicada', 'modelo', '24774f75de79afba021817dda6122e02', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a1b09923-82b3-4244-a31c-87b0b50db12a', 1, 'La línea continua de la especie nativa aumenta y la discontinua de la introducida disminuye. La predicción solicitada prolonga esas tendencias bajo condiciones constantes.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f5dbf930-aaa0-465a-b1d8-4e3a72e49ecf', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  'cb3f1bc5-dd13-4020-8f05-aa10817ab03d', 'Sistemas del cuerpo humano',
  '¿Cuál de las siguientes es una posible consecuencia de la deficiencia de yodo en el organismo?',
  array['Baja producción de la hormona T₄ y poca actividad de la glándula pituitaria.', 'Alta producción de las hormonas T₃ y T₄ e hiperactividad de la glándula pituitaria.', 'Alta producción de la hormona T₃ y poca actividad de la glándula tiroides.', 'Baja producción de las hormonas T₃ y T₄ e hiperactividad de la glándula pituitaria.'],
  'Separa la falta de materia prima de la señal que intenta compensarla.', 'publicada', 'modelo', 'ebff8216d57322328190a2592d291424', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f5dbf930-aaa0-465a-b1d8-4e3a72e49ecf', 3, 'Al faltar yodo se limita la producción de hormonas tiroideas; la disminución de estas aumenta el estímulo de la pituitaria por retroalimentación negativa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b28855c1-a954-4c39-b3d9-8a29fa65e83e', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '0739c9bb-5811-459f-b08a-152471346d59', 'Célula y sus procesos',
  'Según las características de las células X, Y y Z estas podrían pertenecer respectivamente a los reinos',
  array['Vegetal, Fungi y monera.', 'Vegetal, Protista y monera.', 'Animal, vegetal y vegetal.', 'Animal, animal y vegetal.'],
  'Busca primero pared celular y clorofila.', 'publicada', 'modelo', '33fea859de9cb5b467727e52a256d90e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b28855c1-a954-4c39-b3d9-8a29fa65e83e', 3, 'X e Y carecen de pared celular y clorofila, como las células animales; Z posee ambas características, compatibles con una célula vegetal.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '732af9bc-8d65-4c5d-8ee4-dee156ffef11', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '0739c9bb-5811-459f-b08a-152471346d59', 'Célula y sus procesos',
  'Al analizar las características, puede afirmarse que las células',
  array['Y y Z presentan la misma resistencia a aumentar de tamaño.', 'X y Y son heterótrofos porque carecen del pigmento clorofila.', 'Y y X presentan la misma cantidad de información genética.', 'X y Z elaboran su propio alimento porque hacen fotosíntesis.'],
  'Cruza las características de la tabla, sin atribuir fotosíntesis a X.', 'publicada', 'modelo', 'f2f42af3744e6d7c66be0317a53a19b9', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('732af9bc-8d65-4c5d-8ee4-dee156ffef11', 1, 'En la clasificación de organismos pluricelulares usada en el ejercicio, X e Y son compatibles con células animales heterótrofas. Z posee clorofila y pared; X e Y tienen distinta dotación cromosómica. La ausencia de clorofila por sí sola no es una definición universal de heterotrofía.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd16ec912-346c-47ae-92bc-bb8a7f488f18', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '0739c9bb-5811-459f-b08a-152471346d59', 'Célula y sus procesos',
  'Según el número de cromosomas se puede afirmar que la célula',
  array['Z se generó por mitosis y X por meiosis.', 'Z se generó por meiosis y Y por mitosis.', 'X se generó por mitosis y Y por meiosis.', 'X se generó por meiosis y Z por mitosis.'],
  'Relaciona la reducción cromosómica con la meiosis.', 'publicada', 'modelo', '0a8f21b1812dd9da336427ab818f7733', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d16ec912-346c-47ae-92bc-bb8a7f488f18', 2, 'En el modelo animal del ejercicio, la mitosis conserva la dotación diploide y la meiosis produce gametos haploides: X es diploide e Y haploide.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '419e860e-5f54-402d-8977-602b58e8bdd5', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '0739c9bb-5811-459f-b08a-152471346d59', 'Célula y sus procesos',
  'De la tabla de resultados se puede concluir que',
  array['La célula X es somática y la Y es una célula sexual (gameto).', 'Las células Z y Y pertenecen a la misma especie, pero la célula Z es un gameto.', 'La célula X es un gameto y la célula Z presenta una mutación.', 'Las células Z y Y pertenecen a la misma especie, pero presenta una mutación.'],
  'Compara 2n con n y descarta afirmaciones no apoyadas por la tabla.', 'publicada', 'modelo', '48691842cfcc02593181fce34541dee6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('419e860e-5f54-402d-8977-602b58e8bdd5', 0, 'X tiene 40 cromosomas y es diploide; Y tiene 20 y es haploide. Son datos compatibles con una célula somática y un gameto, respectivamente. No hay evidencia de una mutación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a8320853-0d87-4331-9f7f-e80cc7fb09f8', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  null, 'Célula y sus procesos',
  'En las células animales los lisosomas son los organelos encargados de digerir con enzimas los nutrientes que la célula consume. Si todos los lisosomas de una célula se rompieran, ¿qué sucedería inicialmente a la célula?',
  array['Se degradarían moléculas en su interior.', 'Perdería toda el agua del citoplasma.', 'No habría respiración celular.', 'No se formarían proteínas.'],
  'Relaciona la función digestiva del organelo con su contenido.', 'publicada', 'modelo', 'ea4a94eefc2fb580f481d8977c30df9c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a8320853-0d87-4331-9f7f-e80cc7fb09f8', 0, 'La liberación de enzimas digestivas de los lisosomas puede degradar componentes internos. Las otras opciones no describen el efecto inicial asociado a esas enzimas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c1c14fd5-6167-4048-b33e-9b65024f7f30', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '4bcf4c63-9360-40d6-a2ec-efe101314457', 'Genética y herencia',
  '¿Qué le sucede a un organismo si se elimina el gen INS?',
  array['El páncreas bloquea la producción de insulina, lo cual ocasiona que toda la glucosa entre en las células.', 'El páncreas aumenta la producción de proinsulina, lo cual ocasiona un aumento de glucosa en las células.', 'El páncreas no produce más insulina, lo cual ocasiona que la glucosa no pueda ingresar en las células.', 'El páncreas aumenta la producción de la insulina, lo cual ocasiona un aumento de la glucosa en la sangre.'],
  'Sigue la secuencia gen → proteína precursora → hormona.', 'publicada', 'modelo', 'e977338e7fce3e8bce49752282f500cc', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c1c14fd5-6167-4048-b33e-9b65024f7f30', 2, 'Sin el gen funcional no se produce su precursor proteico ni la insulina derivada de él. En el modelo del enunciado se afecta la captación de glucosa dependiente de insulina; la opción simplifica el fenómeno, pues no todos los tejidos requieren insulina para captar glucosa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0119c58b-5f9e-472c-8407-690212794f5e', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '4bca31c6-41fa-4888-a38c-cb4f5d6e89c5', 'Ecosistemas y ciclos',
  'Con base en la información anterior, ¿cuáles de estas fuentes de energía deberían ser implementadas en esta zona, teniendo en cuenta las características del ecosistema y el impacto que pueden tener en la comunidad?',
  array['Los paneles solares y energía eólica.', 'Los biocombustibles y los paneles solares.', 'Únicamente la energía eólica.', 'Únicamente los biocombustibles.'],
  'Busca fuentes que aprovechen recursos abundantes y ahorren el recurso limitante.', 'publicada', 'modelo', '17f65c1e6b17d26969c245653a319f43', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0119c58b-5f9e-472c-8407-690212794f5e', 0, 'El desierto ofrece radiación solar y viento, y ambas fuentes requieren poca agua según la tabla. Los biocombustibles demandan mucha agua, que es escasa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'cec8a4d4-bc98-4de2-8dd7-3f04e833e253', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '4bca31c6-41fa-4888-a38c-cb4f5d6e89c5', 'Ecosistemas y ciclos',
  'Teniendo en cuenta esta información un grupo de estudiantes planteó la siguiente hipótesis: «La escasez de agua en la región aumentará en los próximos años debido al calentamiento global». Ahora bien, si esta hipótesis es correcta, ¿cómo se espera que se vea afectada la producción de energía por medio de biocombustibles con respecto a la producción del año 2019?',
  array['<img src="img/figuras/bio/b5-q113-a.webp" alt="Gráfica con producción que primero desciende y luego aumenta." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q113-b.webp" alt="Gráfica con producción creciente de 2019 a 2024." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q113-c.webp" alt="Gráfica con producción decreciente de 2019 a 2024." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q113-d.webp" alt="Gráfica con producción constante de 2019 a 2024." loading="lazy" style="width:100%;height:auto">'],
  'Relaciona la dependencia del agua con la tendencia prevista.', 'publicada', 'modelo', 'b02d30e4ea0e3dc276acec6a35d1cccf', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cec8a4d4-bc98-4de2-8dd7-3f04e833e253', 2, 'Los biocombustibles requieren un gasto alto de agua. Si aumenta la escasez, se espera una disminución de su producción, representada por la serie de barras descendentes.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '875f2118-ee2e-4346-886b-a7ce708e2d4e', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '4bca31c6-41fa-4888-a38c-cb4f5d6e89c5', 'Ecosistemas y ciclos',
  'Las algas, en grandes cantidades, son utilizadas como biocombustibles en estos ecosistemas. Dichos organismos, al igual que algunas semillas, pueden permanecer dormidos hasta que surjan las condiciones ideales para su crecimiento. Ahora bien, teniendo en cuenta la información sobre los biocombustibles, ¿cuál de los siguientes modelos se ajustaría mejor al crecimiento de las algas en los ecosistemas?',
  array['<img src="img/figuras/bio/b5-q114-a.webp" alt="Modelo con recolección durante el reposo y reproducción al finalizar las lluvias." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q114-b.webp" alt="Modelo con crecimiento durante la sequía y recolección durante la reproducción." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q114-c.webp" alt="Modelo con crecimiento tras comenzar las lluvias, abundancia para recolección y reposo con la sequía." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q114-d.webp" alt="Modelo con recolección durante el crecimiento y lluvias después de la reproducción." loading="lazy" style="width:100%;height:auto">'],
  'Comprueba la relación entre lluvia, crecimiento, abundancia y reposo.', 'publicada', 'modelo', 'b0e30d843506024a88cff3113432fc8c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('875f2118-ee2e-4346-886b-a7ce708e2d4e', 2, 'El modelo compatible sitúa la salida del reposo y el crecimiento tras el inicio de las lluvias, permite recolectar cuando hay abundancia y retorna al reposo al aumentar la sequía.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '051baed5-431e-42d8-a5f8-91fd7f5b1049', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '812ff4a6-e012-4cde-af76-b961df124354', 'Genética y herencia',
  'Si se requiere obtener una producción en la que todos los huevos sean grandes y con cáscara resistente es necesario cruzar gallinas con genotipos.',
  array['GGRR × GgRr.', 'GgRr × ggrr.', 'GgRr × GgRr.', 'GGRr × GgRr.'],
  'Busca un progenitor que garantice ambos alelos dominantes.', 'publicada', 'modelo', '0753008ddcab7d4d231cb5960f0bd6c8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('051baed5-431e-42d8-a5f8-91fd7f5b1049', 0, 'El progenitor GGRR siempre aporta los alelos dominantes G y R. Toda la descendencia tendrá al menos una copia dominante para ambos caracteres. Los otros cruces permiten descendientes rr o gg.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'db1c0607-35a9-4d8b-b657-cf682e8a00aa', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '59c7e6b4-27d4-4047-becc-805980d13f86', 'Genética y herencia',
  '¿Cuál de los siguientes modelos representa adecuadamente el patrón de herencia de esta familia?',
  array['<img src="img/figuras/bio/b5-q116-a.webp" alt="Madre portadora y padre sano; una hija portadora, una sana, un hijo sano y otro con el alelo defectuoso." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q116-b.webp" alt="Padre con el alelo defectuoso y madre sana; dos hijas portadoras y dos hijos sanos." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q116-c.webp" alt="Madre portadora y padre sano; dos hijas portadoras y dos hijos sanos." loading="lazy" style="width:100%;height:auto">', '<img src="img/figuras/bio/b5-q116-d.webp" alt="Ambos padres con el alelo defectuoso; hijas afectadas e hijos con el alelo defectuoso." loading="lazy" style="width:100%;height:auto">'],
  'Distingue un resultado posible en cuatro hijos de una proporción garantizada en toda la descendencia.', 'borrador', 'modelo', 'b1637edc1f697c885d5c3db46e469230', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('db1c0607-35a9-4d8b-b657-cf682e8a00aa', 1, 'Pregunta retenida para revisión: tanto el modelo de padre afectado y madre sana como el de madre portadora y padre sano pueden producir la familia observada. El primero garantiza ese resultado por sexo; el segundo lo permite por azar. El enunciado describe una familia, no exige un resultado garantizado, por lo que no hay una única opción inequívoca.');

